={{
  JSON.stringify({
    model: "openrouter/free",
    temperature: 0.2,
    messages: [
      {
        role: "system",
        content: `You are "Jev", the Senior Technical Evaluator AI Agent for Sunny.

Your mission is to evaluate a candidate's completed answers to the 5 technical qualifying questions they were assigned during Stage 1 screening.

ASSESSMENT CRITERIA:
1. Technical Depth: Concrete, verifiable technical details (e.g., specific HTTP error codes, OAuth scopes, schema structures).
2. Problem-Solving & Debug Mindset: Systematic root-cause troubleshooting rather than guesswork.
3. Production Hardening: Defensive reliability (retries, timeouts, logging, dead-letter queues).
4. Practical Alignment: How well does their problem-solving align with high-volume, middle-of-the-company operational workflows?

OUTPUT FORMAT:
Respond with ONLY a raw unformatted JSON object. Do NOT wrap in markdown backticks.

SCHEMA:
{
  "applicant_name": string,
  "answer_evaluations": [
    { "question_id": number, "score": number, "notes": string }
  ],
  "overall_qualifying_score": number,
  "recommendation": "ADVANCE" | "HOLD",
  "summary_for_hiring_manager": string,
  "suggested_interview_focus": string
}`
      },
      {
        role: "user",
        content: `Candidate Submission to Evaluate:
Full Name: ${$('Lookup Stage 1 Profile').item.json['Full Name']}
Email: ${$('Lookup Stage 1 Profile').item.json['Email']}
Position: ${$('Lookup Stage 1 Profile').item.json['Position']}
Stage 1 Score: ${$('Lookup Stage 1 Profile').item.json['Overall Score']}
Stage 1 Reasoning: ${$('Lookup Stage 1 Profile').item.json['Jev Reasoning']}
Portfolio URL: ${$('Lookup Stage 1 Profile').item.json['Portfolio URL']}

Candidate Answers:
${$('Qualifying Intake Webhook').item.json.body.answers.map(a => `Question ${a.question_id}: ${a.question}\nAnswer: ${a.answer}`).join('\n\n')}`
      }
    ]
  })
}}

parameters.jsCode:
const rawContent = $json.choices[0].message.content;

// 1. Defensive cleanup: strip markdown fences
let cleaned = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();

// 2. Self-healing: slice strictly between the first { and last }
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse Jev Stage 2 evaluation JSON: " + e.message + " | Raw: " + rawContent);
}

// 3. Hydrate Stage 1 context & calculate weighted score
const stage1Data = $('Lookup Stage 1 Profile').item.json;
const stage1Score = Number(stage1Data['Overall Score']) || 0;
const stage2Score = Number(parsed.overall_qualifying_score) || 0;

// Combined score: 40% Stage 1 Screening + 60% Stage 2 Technical Depth
const combinedScore = Math.round((stage1Score * 0.4 + stage2Score * 0.6) * 10) / 10;

// Business Decision: ADVANCE (>= 70) vs HOLD (< 70)
const recommendation = (parsed.recommendation && parsed.recommendation.toUpperCase() === 'ADVANCE') || stage2Score >= 70 
  ? 'ADVANCE' 
  : 'HOLD';

// Title-case applicant name
const applicantName = (parsed.applicant_name || stage1Data['Full Name'] || 'Applicant')
  .trim()
  .replace(/\s+/g, ' ')
  .toLowerCase()
  .replace(/\b\w/g, c => c.toUpperCase());

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      applicant_name: applicantName,
      email: stage1Data['Email'] || $('Qualifying Intake Webhook').item.json.body.applicant_email,
      position: stage1Data['Position'] || 'AI Operator',
      stage1_score: stage1Score,
      stage2_score: stage2Score,
      combined_score: combinedScore,
      recommendation: recommendation,
      summary_for_hiring_manager: parsed.summary_for_hiring_manager || 'Candidate completed Stage 2 technical evaluation.',
      suggested_interview_focus: parsed.suggested_interview_focus || 'Review error handling and architecture.',
      answer_evaluations: parsed.answer_evaluations || []
    }
  }
];
